INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28665$nota-0123$m28665$, $m28666$Training and Racing with a Power Meter.pdf$m28666$, $m28667$358$m28667$, $m28668$When you download racing data, you can see how many kilojoules of energy and TSS points you scored before you became tired, and subsequently you can determine how many calories you need to consume during your next race. For example, if you did a 2.5-hour race and consumed 500 kcals during the race, but then downloaded your race file and found out that you expended 2,000 kJ, or roughly 2,200 kcals, you might plan to eat more during your next race or load up on carbs in the days leading up to the race.$m28668$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28669$nota-0123$m28669$, $m28670$nota-0062$m28670$, $m28671$complementa$m28671$, $m28672$usa o mesmo dado de trabalho mecânico (kJ) que também alimenta o cálculo de TSS (nota-0062), agora aplicado ao planejamento nutricional$m28672$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28673$nota-0123$m28673$, $m28674$nota-0002$m28674$, $m28675$complementa$m28675$, $m28676$nota-0002 trata a mesma conversão kJ→kcal de forma mais geral (simplificação 1:1 do capítulo introdutório, p. 32-33); esta nota usa o exemplo real do capítulo de nutrição em prova (p. 358), com razão ~1:1,1 — ambas do mesmo livro, ver ressalva de precisão em nota-0002$m28676$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28677$nota-0155$m28677$, $m28678$Manual treinamento.pdf$m28678$, $m28679$44$m28679$, $m28680$Durante exercícios leves predominam os lipídios. À medida que a intensidade aumenta, cresce progressivamente a participação dos carboidratos. Essa mudança não ocorre de forma abrupta... Esse fenômeno é conhecido como crossover metabólico.$m28680$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28681$nota-0155$m28681$, $m28682$nota-0156$m28682$, $m28683$complementa$m28683$, $m28684$flexibilidade metabólica (nota-0156), citada no corpo da nota como a capacidade treinável relacionada ao deslocamento do ponto de crossover — nota-0156 já cita nota-0155 de volta; link estrutural nesta direção estava ausente até auditoria de 2026-08-02$m28684$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28685$nota-0156$m28685$, $m28686$Manual treinamento.pdf$m28686$, $m28687$45$m28687$, $m28688$A flexibilidade metabólica representa a capacidade do organismo de alternar rapidamente entre diferentes fontes de energia conforme as necessidades do exercício... Nos últimos anos, a flexibilidade metabólica tornou-se um dos conceitos centrais na fisiologia do endurance.$m28688$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28689$nota-0156$m28689$, $m28690$nota-0155$m28690$, $m28691$complementa$m28691$, $m28692$a flexibilidade metabólica é a capacidade treinável que determina onde/quão suavemente ocorre o crossover metabólico descrito na nota-0155$m28692$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28693$nota-0201$m28693$, $m28694$Manual treinamento.pdf$m28694$, $m28695$237$m28695$, $m28696$Até 60 minutos: normalmente não necessária*. 1–2 horas: 30–60 g/h. 2–3 horas: 60–90 g/h. Acima de 3 horas: 90–120 g/h (quando treinado). * Em provas muito intensas próximas de 60 minutos, pequenas quantidades ou bochechos com carboidrato podem melhorar o desempenho.$m28696$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28697$nota-0201$m28697$, $m28698$nota-0202$m28698$, $m28699$complementa$m28699$, $m28700$carboidratos múltiplos (glicose+frutose) aumentam a absorção intestinal, relevante para atingir as faixas mais altas desta tabela (90-120g/h) sem desconforto gastrointestinal$m28700$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28701$nota-0201$m28701$, $m28702$nota-0227$m28702$, $m28703$complementa$m28703$, $m28704$nota-0227 cobre o protocolo paralelo de reposição de fluido (McArdle) e cita uma faixa geral de 30-60g/h sem escalonar por duração — coincide com esta tabela só na janela de 1-2h; para sessões mais longas, esta tabela (mais granular) deve prevalecer$m28704$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28705$nota-0202$m28705$, $m28706$Manual treinamento.pdf$m28706$, $m28707$237$m28707$, $m28708$A glicose utiliza principalmente o transportador SGLT1. A frutose utiliza predominantemente o GLUT5. Ao combinar diferentes tipos de carboidratos, torna-se possível aumentar a absorção intestinal e reduzir o risco de desconforto gastrointestinal. Essa estratégia permitiu elevar significativamente a ingestão horária de carboidratos em atletas altamente treinados.$m28708$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28709$nota-0202$m28709$, $m28710$Manual treinamento.pdf$m28710$, $m28711$238$m28711$, $m28712$o trato gastrointestinal também pode ser treinado. A prática repetida de ingestão de carboidratos durante os treinos promove adaptações como: maior velocidade de esvaziamento gástrico; aumento da capacidade de absorção; redução do desconforto gastrointestinal; melhor tolerância a grandes quantidades de carboidratos.$m28712$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28713$nota-0202$m28713$, $m28714$nota-0201$m28714$, $m28715$pre-requisito$m28715$, $m28716$explica o mecanismo que permite atingir as faixas mais altas (90-120g/h) da tabela de ingestão da nota-0201, e por que exige treino prévio do intestino$m28716$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28717$nota-0203$m28717$, $m28718$Manual treinamento.pdf$m28718$, $m28719$245$m28719$, $m28720$Durante muitos anos acreditou-se que existia uma 'janela anabólica' extremamente curta, limitada aos primeiros 30 minutos após o exercício. Hoje a evidência científica mostra uma visão mais equilibrada... essa janela dura várias horas; sua importância depende do estado nutricional prévio; o consumo total diário de energia e proteínas exerce influência ainda maior.$m28720$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28721$nota-0204$m28721$, $m28722$Manual treinamento.pdf$m28722$, $m28723$246$m28723$, $m28724$Cafeína: possui uma das maiores quantidades de evidências favoráveis... Creatina: pode beneficiar sprint, acelerações repetidas, treinamento de força, manutenção da massa muscular. Seu impacto sobre provas longas é menor.$m28724$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28725$nota-0204$m28725$, $m28726$Manual treinamento.pdf$m28726$, $m28727$247$m28727$, $m28728$Bicarbonato de sódio: atua aumentando a capacidade tamponante do organismo. Pode beneficiar exercícios intensos entre aproximadamente 1 e 10 minutos... Nitrato (suco de beterraba): pode melhorar a eficiência muscular... maiores benefícios tendem a ocorrer em atletas moderadamente treinados... Beta-alanina: aumenta os estoques musculares de carnosina. Pode melhorar a capacidade de sustentar exercícios de alta intensidade com duração entre aproximadamente 1 e 4 minutos.$m28728$);
